  const [isLoading, setLoading] = useState(false);
  const [isSuccess, setSuccess] = useState(false);
  const [isError, setError] = useState(false);
  const handleSave = () => {
    setLoading(true);
    setSuccess(false);
    setError(false);
    const hasError = Math.random() < 0.5;
    setTimeout(() => {
      if (hasError) {
        setLoading(false);
        setError(true);
      } else {
        setSuccess(true);
        setLoading(false);
      }
    }, 4000);
  };
  return <BasePage headerSlot={<AutoSaveIndicator onRetry={() => {
    handleSave();
  }} isLoading={isLoading} isError={isError} isSuccess={isSuccess} errorMsg="Ошибка автосохранения" />} onSave={handleSave} />;
